    'Advanced': '高级',
    'Advanced Configuration': '高级配置',
    'Modes': '模式',
    'Local': '本地',
    'Regular': '常规',
    'Reverse': '反向',
    'Forward': '转发',
    'Transparent': '透明',
    'Socks': 'SOCKS',
    'Upstream': '上游',
    'Dns': 'DNS',
    'Wireguard': 'WireGuard',
    'History': '历史',
    'Selection': '选区',
    'Range': '范围',
    'Delayed': '已延迟',
    'Aborted': '已中止',
    'Rejected': '已拒绝',
    // ===== 空状态/提示 =====
    'mitmproxy is running.': 'mitmproxy 正在运行。',
    'No flows have been recorded yet.': '尚未记录到任何流量。',
    'To start capturing traffic, please configure your settings in the Capture tab.': '要开始捕获流量，请在「抓包」选项卡中配置相关设置。',
    'This document is already in use.': '此文档正在使用中。',
    'Upload a file to replace the content.': '上传文件以替换内容。',
    'Connection killed.': '连接已终止。',
    // ===== 抓包(Capture)页 =====
    'Intercept Traffic': '拦截流量',
    'Configure how you want to intercept traffic with mitmproxy.': '配置 mitmproxy 的流量拦截方式。',
    'Explicit HTTP(S) Proxy': '显式 HTTP(S) 代理',
    'You manually configure your client application or device to use an HTTP(S) proxy.': '手动将客户端程序或设备配置为使用 HTTP(S) 代理。',
    'Run HTTP/S Proxy': '运行 HTTP/S 代理',
    'Listen Host': '监听地址',
    'Listen Port': '监听端口',
    'Transparent Proxy': '透明代理',
    'Run Transparent Proxy': '运行透明代理',
